begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select extensions.no_plan();
select extensions.ok(not has_function_privilege('authenticated','pickleup_private.operation_core(uuid,text,text,text,text,jsonb,integer,jsonb)','EXECUTE'),'import context worker is private');
select extensions.ok(not has_function_privilege('authenticated','pickleup_private.import_change(text,text,jsonb)','EXECUTE'),'change writer is private');
select extensions.ok(not has_function_privilege('anon','public.begin_import(uuid,text,text,text,text,integer,jsonb,integer)','EXECUTE'),'anonymous cannot begin import');
select extensions.ok(not has_function_privilege('anon','public.import_batch(uuid,uuid,text,jsonb,integer)','EXECUTE'),'anonymous cannot import batch');
select extensions.ok(not has_function_privilege('anon','public.finish_import(uuid,uuid,text,boolean,integer)','EXECUTE'),'anonymous cannot finish import');
select extensions.ok(not has_function_privilege('anon','public.get_import_status(uuid,integer)','EXECUTE'),'anonymous cannot inspect import');
select extensions.ok(not has_table_privilege('authenticated','public.legacy_imports','INSERT'),'manifest direct insert remains denied');
select extensions.ok(not has_table_privilege('authenticated','public.legacy_import_items','UPDATE'),'mapping direct update remains denied');
select extensions.ok((select bool_and(p.prosecdef and p.proowner='pickleup_api'::regrole and p.proconfig @> array['search_path=""']) from pg_proc p where p.oid in ('public.begin_import(uuid,text,text,text,text,integer,jsonb,integer)'::regprocedure,'public.import_batch(uuid,uuid,text,jsonb,integer)'::regprocedure,'public.finish_import(uuid,uuid,text,boolean,integer)'::regprocedure,'public.get_import_status(uuid,integer)'::regprocedure)),'all import RPCs use narrow owner and empty search path');
select extensions.ok(not exists(select 1 from pg_roles where rolname='pickleup_api' and (rolsuper or rolbypassrls or rolcanlogin)),'RPC owner remains non-login non-bypass');
select extensions.ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in ('public.legacy_imports'::regclass,'public.legacy_import_items'::regclass,'public.legacy_score_snapshots'::regclass)),'import tables retain forced RLS');
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select extensions.is(public.begin_import(gen_random_uuid(),repeat('a',64),repeat('b',64),'test','test',1)->>'status','auth_required','missing identity cannot begin');
select extensions.is(public.import_batch(gen_random_uuid(),gen_random_uuid(),'1','[]')->>'status','auth_required','missing identity cannot batch');
select extensions.is(public.finish_import(gen_random_uuid(),gen_random_uuid(),'1')->>'status','auth_required','missing identity cannot finish');
select extensions.is(public.get_import_status(gen_random_uuid())->>'status','auth_required','missing identity cannot inspect');
reset role;
select * from extensions.finish();
rollback;
